def count_nums(arr):
    def sum_of_digits(n):
        if n < 0:
            # Convert the number to a string and remove the negative sign
            n_str = str(n)[1:]
            # Calculate the sum of digits, considering the first digit as negative
            return int(n_str[0]) + sum(int(digit) for digit in n_str[1:])
        else:
            # Calculate the sum of digits for positive numbers
            return sum(int(digit) for digit in str(n))

    return sum(1 for num in arr if sum_of_digits(num) > 0)

