from collections import Counter

def match_parens(lst):
    def is_balanced(s):
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    # Count the total number of opening and closing parentheses
    total_open = sum(Counter(lst[0]).values())
    total_close = sum(Counter(lst[1]).values())

    # Check if the total number of opening and closing parentheses are equal
    if total_open != total_close:
        return 'No'

    # Check if either string is already balanced
    if is_balanced(lst[0]) or is_balanced(lst[1]):
        return 'Yes'

    # Try concatenating in both possible orders
    if is_balanced(lst[0] + lst[1]) or is_balanced(lst[1] + lst[0]):
        return 'Yes'

    return 'No'

from datetime import datetime

def valid_date(date):
    # Check if the date string is empty
    if not date:
        return False

    # Check if the date string matches the required format
    try:
        datetime.strptime(date, '%m-%d-%Y')
    except ValueError:
        return False

    # Extract month and day from the date string
    month, day, year = map(int, date.split('-'))

    # Check if the month is between 1 and 12
    if month < 1 or month > 12:
        return False

    # Check if the day is within the valid range for the given month
    if month in [1, 3, 5, 7, 8, 10, 12]:
        if day < 1 or day > 31:
            return False
    elif month in [4, 6, 9, 11]:
        if day < 1 or day > 30:
            return False
    else:  # month is 2 (February)
        if day < 1 or day > 29:
            return False

    return True

