def do_algebra(operator, operand):
    # Start with the first operand
    result = operand[0]

    # Iterate over the operators and operands
    for i in range(len(operator)):
        if operator[i] == '+':
            result += operand[i + 1]
        elif operator[i] == '-':
            result -= operand[i + 1]
        elif operator[i] == '*':
            result *= operand[i + 1]
        elif operator[i] == '//':
            result //= operand[i + 1]
        elif operator[i] == '**':
            result **= operand[i + 1]
        else:
            raise ValueError(f"Unsupported operator: {operator[i]}")

    return result

