def encrypt(s):
    def rotate_char(c):
        if c.isalpha():
            start = ord('a') if c.islower() else ord('A')
            return chr((ord(c) - start + 2 * 2) % 26 + start)
        return c

    return ''.join(rotate_char(c) for c in s)

