def find_First_Missing(array, start=0, end=None):
    if end is None:
        end = len(array) - 1

    # If the array is empty or the first element is not 0, return 0
    if start == end and array[start] != 0:
        return 0

    # Iterate through the array
    for i in range(start, end + 1):
        # If the current element is not equal to its index + start, return the index + start
        if array[i] != i + start:
            return i + start

    # If no missing number is found, return the next index
    return end + 1

# Example usage:
array = [0, 1, 2, 3, 4, 5, 6, 7, 9]
print(find_First_Missing(array))  # Output: 8

