def count_Substrings(s):
    def is_valid_substring(sub):
        return sum(int(digit) for digit in sub) == len(sub)

    count = 0
    n = len(s)

    # Iterate over all possible substrings
    for i in range(n):
        for j in range(i + 1, n + 1):
            if is_valid_substring(s[i:j]):
                count += 1

    return count

