    if not isinstance(Input, list) or not all(isinstance(item, tuple) for item in Input):
        return False

    # Get the length of the first tuple
    first_tuple_length = len(Input[0])

    # Check if all tuples have the same length as the first tuple
    for tup in Input:
        if len(tup) != first_tuple_length:
            return False

    return True

def comb_sort(nums):
    gap = len(nums)
    shrink_factor = 1.3
    sorted = False

    while not sorted:
        gap = int(gap / shrink_factor)
        if gap < 1:
            gap = 1
        sorted = True

        for i in range(0, len(nums) - gap):
            if nums[i] > nums[i + gap]:
                nums[i], nums[i + gap] = nums[i + gap], nums[i]
                sorted = False

    return nums

def is_samepatterns(colors, patterns):
    # Check if the number of colors matches the number of patterns
    if len(colors) != len(patterns):
        return False

    # Iterate over each color and pattern pair
    for color, pattern in zip(colors, patterns):
        # Check if the color matches the pattern
        if color != pattern:
            return False

    # If all checks pass, the sequences match
    return True

