def get_total_number_of_sequences(m, n):
    # Initialize a DP table where dp[i][j] represents the number of sequences of length i ending with j
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: There's one way to form a sequence of length 1 with any number from 1 to m
    for i in range(1, m + 1):
        dp[1][i] = 1

    # Fill the DP table
    for length in range(2, n + 1):
        for end in range(1, m + 1):
            for prev in range(1, end // 2 + 1):
                if prev * 2 <= end <= m:
                    dp[length][end] += dp[length - 1][prev]

    # The total number of sequences of length n is the sum of all sequences ending with numbers from 1 to m
    return sum(dp[n])

# Example usage:
print(get_total_number_of_sequences(5, 3))  # Output: 10

def max_sum(arr):
    n = len(arr)

    # Initialize two arrays to store the maximum sum of increasing and decreasing subsequences
    inc = [0] * n
    dec = [0] * n

    # Fill inc[] such that inc[i] contains the maximum sum of increasing subsequence ending with arr[i]
    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # Fill dec[] such that dec[i] contains the maximum sum of decreasing subsequence starting with arr[i]
    for i in range(n - 1, -1, -1):
        dec[i] = arr[i]
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    # The maximum sum of bitonic subsequence will be the maximum value in inc[] + dec[]
    max_bitonic_sum = 0
    for i in range(n):
        max_bitonic_sum = max(max_bitonic_sum, inc[i] + dec[i] - arr[i])

    return max_bitonic_sum

# Example usage:
