def check_greater(arr, number):
    # Check if the number is greater than all elements in the array
    return all(number > x for x in arr)

import re

def text_match_one(text):
    # Use regular expression to find a string that starts with 'a' followed by one or more 'b's
    pattern = r'^a+b$'
    if re.search(pattern, text):
        return True
    else:
        return False

