def surfacearea_cube(l):
    # The surface area of a cube is 6 times the area of one face
    return 6 * l ** 2

def largest_neg(list1):
    # Initialize the largest_neg variable to None
    largest_neg = None

    # Iterate through each element in the list
    for num in list1:
        # Check if the current number is negative and either largest_neg is None or the current number is greater than largest_neg
        if num < 0 and (largest_neg is None or num > largest_neg):
            largest_neg = num

    # Return the largest_neg found, or None if no negative numbers were found
    return largest_neg

def count_Occurrence(tup, lst):
    # Create a dictionary to store the count of each element in the list
    count_dict = {}

    # Iterate over each element in the list
    for element in lst:
        # If the element is already in the dictionary, increment its count
        if element in count_dict:
            count_dict[element] += 1
        # Otherwise, add the element to the dictionary with a count of 1
        else:
            count_dict[element] = 1

    # Create a new tuple to store the results
    result_tuple = ()

    # Iterate over each element in the tuple
    for element in tup:
        # If the element is in the dictionary, add its count to the result tuple
        if element in count_dict:
            result_tuple += (count_dict[element],)
        # Otherwise, add 0 to the result tuple
        else:
            result_tuple += (0,)

    return result_tuple

# Example usage:
tup = (1, 2, 3, 4, 5)
lst = [1, 2, 2, 3, 3, 3, 4, 4, 4, 4]
print(count_Occurrence(tup, lst))  # Output: (1, 2, 3, 4, 5)

def cal_sum(n):
    if n <= 0:
        return 0
    elif n == 1:
        return 3
    elif n == 2:
        return 5

    # Initialize the first three Perrin numbers
    p0, p1, p2 = 3, 5, 8

    # Calculate the sum of the first n Perrin numbers
    total_sum = p0 + p1 + p2
    for i in range(3, n):
        next_perrin = p0 + p1
        total_sum += next_perrin
        p0, p1, p2 = p1, p2, next_perrin

    return total_sum

def loss_amount(actual_cost, sale_amount):
    if actual_cost > sale_amount:
        return actual_cost - sale_amount
    else:
        return 0

import re

def text_match_wordz(text):
    # Use regular expression to find words containing 'z'
    pattern = r'\b\w*z\w*\b'
    match = re.search(pattern, text)
    if match:
        return True
    else:
        return False

def Find_Min(lst):
    if not lst:
        return None  # Return None if the list is empty

    min_length = float('inf')
    min_sublist = None

    for sublist in lst:
        if len(sublist) < min_length:
            min_length = len(sublist)
            min_sublist = sublist

    return min_sublist

def max_subarray_product(arr):
    if not arr:
        return 0

    max_product = min_product = result = arr[0]

    for num in arr[1:]:
        if num < 0:
            max_product, min_product = min_product, max_product

        max_product = max(num, max_product * num)
        min_product = min(num, min_product * num)

        result = max(result, max_product)

    return result

def check_value(dict, n):
    # Check if the dictionary is empty
    if not dict:
        return True

    # Get the first value from the dictionary
    first_value = next(iter(dict.values()))

    # Compare each value in the dictionary with the first value
    for value in dict.values():
        if value != first_value:
            return False

    return True

def check_Consecutive(l):
    if len(l) == 0:
        return False

    l.sort()

    for i in range(1, len(l)):
        if l[i] != l[i - 1] + 1:
            return False

    return True

def sort_counter(dict1):
    # Sort the dictionary by values in descending order
    sorted_dict = dict(sorted(dict1.items(), key=lambda item: item[1], reverse=True))
    return sorted_dict

