def amicable_numbers_sum(limit):
    def sum_of_divisors(n):
        """Calculate the sum of proper divisors of n."""
        divisors_sum = 1  # Start with 1 because it's a proper divisor of every number
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                divisors_sum += i
                if i != n // i:  # Avoid adding the square root twice for perfect squares
                    divisors_sum += n // i
        return divisors_sum

    amicable_pairs = set()
    for num in range(2, limit + 1):
        if num not in amicable_pairs:
            partner = sum_of_divisors(num)
            if partner > num and sum_of_divisors(partner) == num:
                amicable_pairs.add(num)
                amicable_pairs.add(partner)

    return sum(amicable_pairs)

# Example usage:
print(amicable_numbers_sum(3000))  # Output will depend on the definition of amicable numbers up to 3000

def sum(a, b):
    # Helper function to calculate the greatest common divisor (GCD)
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    # Calculate the GCD of the two numbers
    common_divisor_gcd = gcd(a, b)

    # Calculate the sum of all divisors of the GCD
    sum_of_divisors = 0
    for i in range(1, common_divisor_gcd + 1):
        if common_divisor_gcd % i == 0:
            sum_of_divisors += i

    return sum_of_divisors

def magic_square_test(my_matrix):
    n = len(my_matrix)
    if n == 0:
        return False

    # Calculate the sum of the first row to use as a reference
    magic_sum = sum(my_matrix[0])

    # Check rows and columns
    for i in range(n):
        if sum(my_matrix[i]) != magic_sum or sum([my_matrix[j][i] for j in range(n)]) != magic_sum:
            return False

    # Check diagonals
    if sum([my_matrix[i][i] for i in range(n)]) != magic_sum or sum([my_matrix[i][n-i-1] for i in range(n)]) != magic_sum:
        return False

    return True

def reverse_vowels(str1):
    vowels = "aeiouAEIOU"
    str1 = list(str1)
    left, right = 0, len(str1) - 1

    while left < right:
        if str1[left] not in vowels:
            left += 1
        elif str1[right] not in vowels:
            right -= 1
        else:
            str1[left], str1[right] = str1[right], str1[left]
            left += 1
            right -= 1

    return ''.join(str1)

# Test the function
